/**
 * Erzeugt docs/social-preview.png - das Bild, das GitHub, Slack und LinkedIn
 * zeigen, wenn jemand einen Link auf das Repository teilt.
 *
 *   npm run social
 *
 * Das Ergebnis muss einmal von Hand hochgeladen werden: GitHub bietet dafuer
 * keine API, nur Settings -> General -> Social preview.
 */
import { chromium } from 'playwright'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const logo = readFileSync(resolve(root, 'docs/logo.svg'), 'utf8')
const shot = readFileSync(resolve(root, 'docs/screenshots/list.png')).toString('base64')

const html = String.raw`<!doctype html><html><head><meta charset="utf-8"><style>
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  width: 1280px; height: 640px; overflow: hidden; position: relative;
  background: #16202b;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #fff;
}
/* Sanfter Farbverlauf aus der Akzentfarbe, damit die Fläche nicht tot wirkt */
body::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(900px 520px at 88% 12%, rgba(43,179,191,.30), transparent 62%);
}
.left { position: absolute; left: 72px; top: 72px; width: 660px; z-index: 2; }
.brand { display: flex; align-items: center; gap: 18px; margin-bottom: 44px; }
.brand svg { width: 62px; height: 62px; border-radius: 14px; display: block; }
.name { font-size: 34px; letter-spacing: -.02em; }
.name .a { font-weight: 400; color: #9fcbcf; }
.name .b { font-weight: 700; color: #fff; }
h1 { font-size: 60px; line-height: 1.06; letter-spacing: -.03em; font-weight: 700; }
h1 .hi { color: #4fc3cd; }
p { margin-top: 26px; font-size: 24px; line-height: 1.45; color: #b6c4d0; max-width: 600px; }
.chips { position: absolute; left: 72px; bottom: 66px; display: flex; gap: 10px; z-index: 2; }
.chip {
  border: 1px solid rgba(159,203,207,.42); color: #9fcbcf;
  border-radius: 999px; padding: 8px 17px; font-size: 16.5px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
/* Screenshot laeuft rechts aus dem Bild - deutet die Anwendung an, ohne
   dass Details lesbar sein muessten */
.shot {
  position: absolute; right: -140px; top: 96px; width: 720px;
  border-radius: 12px; box-shadow: 0 40px 90px -20px rgba(0,0,0,.75);
  transform: rotate(-4deg); z-index: 1;
  border: 1px solid rgba(255,255,255,.14);
}
</style></head><body>
<img class="shot" src="data:image/png;base64,">
<div class="left">
  <div class="brand"><svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="openToolbox logo">
  <title>openToolbox</title>
  <defs>
    <linearGradient id="otb-bg" x1="0" y1="0" x2="100" y2="100" gradientUnits="userSpaceOnUse">
      <stop offset="0" stop-color="#2bb3bf"/>
      <stop offset="1" stop-color="#0b5e66"/>
    </linearGradient>
  </defs>
  <rect x="0" y="0" width="100" height="100" rx="22" fill="url(#otb-bg)"/>
  <path d="M35,20 H57 L73,36 V74 A8,8 0 0 1 65,82 H35 A8,8 0 0 1 27,74 V28 A8,8 0 0 1 35,20 Z" fill="#ffffff"/>
  <path d="M57,20 L57,32 A4,4 0 0 0 61,36 L73,36 Z" fill="#bdeef1"/>
  <rect x="57" y="27" width="27" height="23" rx="7" fill="#ffffff"/>
  <path d="M65.5,38.5 v-4.2 a5,5 0 0 1 10,0 v4.2" fill="none" stroke="url(#otb-bg)" stroke-width="3.2" stroke-linecap="round"/>
  <rect x="63.5" y="38.5" width="14" height="10.5" rx="3" fill="url(#otb-bg)"/>
  <circle cx="70.5" cy="43" r="1.7" fill="#ffffff"/>
  <rect x="69.6" y="43" width="1.8" height="3.4" rx="0.9" fill="#ffffff"/>
</svg>
<span class="name"><span class="a">open</span><span class="b">Toolbox</span></span></div>
  <h1>One HTML file.<br><span class="hi">No server, no install.</span></h1>
  <p>A template for AI coding agents: describe the tool, swap one file, ship the result.</p>
</div>
<div class="chips">
  <span class="chip">file is the database</span>
  <span class="chip">AES-256</span>
  <span class="chip">works offline</span>
</div>
</body></html>`
  .replace('__LOGO__', logo)
  .replace('__SHOT__', shot)

mkdirSync(resolve(root, 'docs'), { recursive: true })
const page = resolve(root, 'docs/.social-preview.html')
writeFileSync(page, html)

const browser = await chromium.launch()
const tab = await browser.newPage({
  viewport: { width: 1280, height: 640 },
  deviceScaleFactor: 2,
})
await tab.goto('file://' + page)
await tab.waitForTimeout(400)
await tab.screenshot({ path: resolve(root, 'docs/social-preview.png') })
await browser.close()

console.log('docs/social-preview.png written — upload it under Settings -> General -> Social preview.')
